const LC_SHA256 = '53dba3e489dd5ba1b9840fc87d2287119d534ef844cc0e73018d3ccfe60952c2';

export function implicitAacFixture(profile: 'he' | 'ps' | 'lc'): Readonly<{ file: File; channels: readonly Float32Array[]; frameCount: number }> {
	const [encoded, reference, hash] = profile === 'he' ? [HE_ENCODED, HE_REFERENCE, HE_SHA256]
		: profile === 'ps' ? [PS_ENCODED, PS_REFERENCE, PS_SHA256] : [LC_ENCODED, LC_REFERENCE, LC_SHA256];
	const bytes = Uint8Array.from(Buffer.from(encoded, 'base64'));
	assert.equal(createHash('sha256').update(bytes).digest('hex'), hash);
	const pcm = inflateSync(Buffer.from(reference, 'base64')), frameCount = pcm.length / 8;
	const channels = [0, 1].map(channel => Float32Array.from({ length: frameCount }, (_, frame) => pcm.readFloatLE((frame * 2 + channel) * 4)));
	return { file: new File([bytes], profile + '.aac', { type: 'audio/aac' }), channels, frameCount };
}
